"""Shopping cart for the checkout service.

A Cart holds line items for one customer. Prices are in cents to avoid float rounding.
"""

from dataclasses import dataclass


@dataclass
class LineItem:
    sku: str
    unit_price_cents: int
    quantity: int = 1

    @property
    def subtotal_cents(self) -> int:
        return self.unit_price_cents * self.quantity


class Cart:
    BULK_THRESHOLD = 10  # 10 or more units of one SKU get the bulk discount
    BULK_DISCOUNT = 0.10

    def __init__(self, customer_id, items=[]):
        self.customer_id = customer_id
        self.items = items

    def add(self, sku, unit_price_cents, quantity=1):
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        for item in self.items:
            if item.sku == sku:
                item.quantity += quantity
                return item
        item = LineItem(sku, unit_price_cents, quantity)
        self.items.append(item)
        return item

    def remove(self, sku):
        self.items = [i for i in self.items if i.sku != sku]

    def item_count(self):
        return sum(i.quantity for i in self.items)

    def total_cents(self):
        total = 0
        for item in self.items:
            line = item.subtotal_cents
            if item.quantity >= self.BULK_THRESHOLD:
                line = round(line * (1 - self.BULK_DISCOUNT))
            total += line
        return total

"""Group raw click events into user sessions for the analytics dashboard.

A session is a run of events from one user where no two consecutive events are more than
SESSION_GAP seconds apart. Events arrive from several ingest workers, so they are NOT guaranteed
to be in timestamp order.
"""

from collections import defaultdict
from dataclasses import dataclass, field

SESSION_GAP = 30 * 60  # seconds of inactivity that end a session


@dataclass
class Event:
    user_id: str
    ts: int  # unix seconds
    page: str


@dataclass
class Session:
    user_id: str
    start: int
    end: int
    pages: list[str] = field(default_factory=list)

    @property
    def duration(self) -> int:
        return self.end - self.start


def sessionize(events):
    """Return {user_id: [Session, ...]} with each user's sessions in chronological order."""
    by_user = defaultdict(list)
    for ev in events:
        by_user[ev.user_id].append(ev)

    result = {}
    for user_id, user_events in by_user.items():
        sessions = []
        current = None
        for ev in user_events:
            if current is None or ev.ts - current.start > SESSION_GAP:
                current = Session(user_id, ev.ts, ev.ts, [ev.page])
                sessions.append(current)
            else:
                current.end = ev.ts
                current.pages.append(ev.page)
        result[user_id] = sessions
    return result


def average_session_seconds(events):
    sessions = [s for user in sessionize(events).values() for s in user]
    if not sessions:
        return 0.0
    return sum(s.duration for s in sessions) / len(sessions)

